-- Generated by `python -m app.seed` from app/seed.py. Do not edit by hand: a test
-- compares this file with the generator. docker-compose runs it on the first boot of
-- the database; the service applies the same statements at start-up when
-- AUTO_CREATE_SCHEMA=true, so a hosted database (Neon) needs no manual step.
-- The LangGraph checkpoint tables are created by langgraph-checkpoint-postgres itself
-- (checkpointer.setup()).

CREATE TABLE IF NOT EXISTS inventory_skus (
    sku_code            TEXT PRIMARY KEY,
    product_name        TEXT NOT NULL,
    npn_number          TEXT NOT NULL,
    dosage_form         TEXT NOT NULL,
    stock_quantity      INTEGER NOT NULL CHECK (stock_quantity >= 0),
    serving_size        TEXT NOT NULL,
    active_ingredients  JSONB NOT NULL,
    authorized_claims   JSONB NOT NULL,
    risk_information    JSONB NOT NULL,
    contraindications   TEXT,
    brand_notes         TEXT,
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS webhook_audit_log (
    id              BIGSERIAL PRIMARY KEY,
    delivery_id     TEXT NOT NULL,
    thread_id       TEXT NOT NULL,
    attempt         INTEGER NOT NULL,
    target_mode     TEXT NOT NULL,
    url_host        TEXT,
    status_code     INTEGER,
    ok              BOOLEAN NOT NULL,
    error           TEXT,
    duration_ms     DOUBLE PRECISION,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_webhook_audit_thread ON webhook_audit_log (thread_id, created_at);

CREATE TABLE IF NOT EXISTS webhook_inbox (
    delivery_id     TEXT PRIMARY KEY,
    thread_id       TEXT,
    received_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    signature_valid BOOLEAN NOT NULL,
    payload         JSONB NOT NULL
);

